    "q": "لو أحرم للعمرة في آخر رجب وأتى بأعمالها في شعبان فإنه يدرك فضل الرجبية بلا خلاف، ولكن لو خرج من مكة بعد العمرة، فهل يجب عليه الإحرام لدخولها في شعبان؟",
