  "umrah_mufrada-037": {
    "q": "مما نسب للإمام السجاد محاورًا الشبلي",
    "cases": [
      {
        "label": "١",
        "opinions": [
          {
            "ruling": "قالَ: فَحينَ نَزَلتَ الميقاتَ نَوَيتَ أنَّكَ خَلَعتَ ثَوبَ المَعصِيَةِ، ولَبِستَ ثَوبَ الطّاعَةِ؟ قالَ: لا. قالَ: فَحينَ تَجَرَّدتَ عَن مَخيطِ ثِيابِكَ نَوَيتَ أنَّكَ تَجَرَّدتَ مِنَ الرِّياءِ والنِّفاقِ والدُّخولِ فِي الشُّبُهاتِ؟ قالَ: لا. قالَ: فَحينَ اغتَسَلتَ نَوَيتَ أنَّكَ اغتَسَلتَ مِنَ الخَطايا والذُّنوبِ؟ قالَ: لا. قالَ: فَما نَزَلتَ الميقاتَ، ولا تَجَرَّدتَ عَن مَخيطِ الثِّيابِ، ولاَ اغتَسَلتَ!",
            "tone": "detail",
            "maraji": []
          }
        ]
      },
      {
        "label": "٢",
        "opinions": [
          {
            "ruling": "قالَ: فَحينَ تَنَظَّفتَ وأحرَمتَ وعَقَدتَ الحَجَّ نَوَيتَ أنَّكَ تَنَظَّفتَ بِنورَةِ التَّوبَةِ الخالِصَةِ للهِ تَعالى؟ قالَ: لا. قالَ: فَحينَ أحرَمتَ نَوَيتَ أنَّكَ حَرَّمتَ عَلى نَفسِكَ كُلَّ مُحَرَّمٍ حَرَّمَهُ اللهُ عَزَّ وجَلَّ؟ قالَ: لا. قالَ: فَحينَ عَقَدتَ الحَجَّ نَوَيتَ أنَّكَ قَد حَلَلتَ كُلَّ عَقدٍ لِغَيرِ اللهِ؟ قالَ: لا. قالَ لَهُ عليه السلام: ما تَنَظَّفتَ، ولا أحرَمتَ، ولا عَقَدتَ الحَجَّ!",
            "tone": "detail",
            "maraji": []
          }
        ]
      },
      {
        "label": "٣",
        "opinions": [
          {
            "ruling": "قالَ: فَحينَ دَخَلتَ الميقاتَ نَوَيتَ أنَّكَ بِنِيَّةِ الزِّيارَةِ؟ قالَ: لا. قالَ: فَحينَ صَلَّيتَ الرَّكعَتَينِ نَوَيتَ أنَّكَ تَقَرَّبتَ إلَى اللهِ بِخَيرِ الأَعمالِ مِنَ الصَّلاةِ وأكبَرِ حَسَناتِ العِبادِ؟ قالَ: لا. قالَ: فَحينَ لَبَّيتَ نَوَيتَ أنَّكَ نَطَقتَ للهِ سُبحانَهُ بِكُلِّ طاعَةٍ وصَمَتَّ عَن كُلِّ مَعصِيَةٍ؟ قالَ: لا. قالَ لَهُ عليه السلام: ما دَخَلتَ الميقاتَ، ولا صَلَّيتَ، ولا لَبَّيتَ!",
            "tone": "detail",
            "maraji": []
          }
        ]
      },
      {
        "opinions": [
          {
            "ruling": "خريطة: المسجد النبوي، مسجد قباء، محطة قطار الحرمين، أبيار علي، جبل عَير. من زاوية سور المسجد النبوي الجنوبية الشرقية إلى محاذاة مسجد الشجرة شرقًا = (6 أميال)، و15 كم (9,32 أميال).",
            "tone": "detail",
            "maraji": []
          }
        ],
        "label": "من مسائل ميقات ذي الحليفة"
      }
    ],
    "status": "draft"
  },
