  "umrah_mufrada-092": {
    "q": "الإحرام — نُسِبَ للإمام الصَّادق عليه السلام",
    "cases": [
      {
        "opinions": [
          {
            "ruling": "إذا أرَدتَ الحَجَّ فَجَرِّد قَلبَكَ للهِ تَعالى مِن كُلِّ شاغِل، وحِجابِ كُلِّ حاجِب. وفَوِّض أُمورَكَ كُلَّها إلى خالِقِكَ، وتَوَكَّل عَلَيهِ في جَميعِ ما يَظهَرُ مِن حَرَكاتِكَ وسَكَناتِكَ، وسَلِّم لِقَضائِهِ وحُكمِهِ وقَدَرِه.. ودَعِ الدُّنيا والرّاحَةَ والخَلقَ، واخرُج مِن حُقوقٍ تَلزَمُكَ مِن جِهَةِ المَخلوقينَ، ولا تَعتَمِد عَلى زادِكَ وراحِلَتِكَ وأصحابِكَ وقُوَّتِكَ وشَبابِكَ ومالِكَ؛ … لَيَعلَمَ أنَّهُ لَيسَ لَهُ قُوَّةٌ ولا حيلَةٌ ولا لأَحَدٍ إلاّ بِعِصمَةِ اللهِ وتَوفيقِهِ، واستَعِدَّ استِعدادَ مَن لا يَرجو الرُّجوعَ، وأحسِنِ الصُّحبَةَ، وراعِ أوقاتَ فَرائِضِ اللهِ وسُنَنِ نَبِيِّهِ (صلى الله عليه وآله) وما يَجِبُ عَلَيكَ مِنَ الأَدَبِ والاِحتِمالِ والصَّبرِ والشُّكرِ والشَّفَقَةِ والسَّخاءِ وإيثارِ الزّادِ عَلى دَوامِ الأَوقاتِ.",
            "tone": "detail",
            "maraji": []
          }
        ]
      },
      {
        "opinions": [
          {
            "ruling": "آداب: قبل الإحرام، أثناء الإحرام، بعد الإحرام.",
            "tone": "detail",
            "maraji": []
          },
          {
            "ruling": "واجبات: النية، لبس ثياب الإحرام، التلبية.",
            "tone": "yes",
            "maraji": []
          },
          {
            "ruling": "محرمات: على الرجال والنساء، على الرجال فقط، على النساء فقط.",
            "tone": "yes",
            "maraji": []
          },
          {
            "ruling": "مكروهات: ١- الإحرام في الثياب: السوداء، الوسخة، المعلَّمة. ٢- النوم على الفراش الأصفر والوسادة الصفراء. ٣- تلبية المنادي.",
            "tone": "detail",
            "maraji": []
          }
        ],
        "label": "الإحرام: آداب، واجبات، محرمات، مكروهات"
      }
    ],
    "status": "draft"
  },
  "umrah_mufrada-094": {
    "q": "آدابٌ قبل الإحرام",
    "cases": [
      {
        "opinions": [
          {
            "ruling": "توفير شعر الرأس قبل شهر لاستحباب الأشعثية ولحلقه عند الإحلال.",
            "tone": "no",
            "maraji": []
          },
          {
            "ruling": "تنظيف الجسد، وإزالة شعر الإبطين والعانة، وإن كان قبل السفر بقصد الإحرام.",
            "tone": "no",
            "maraji": []
          },
          {
            "ruling": "الأخذ من الشارب، وتقليم الأظفار إلا ظفرًا لاستحباب الإحلال بالشعر والأظفار.",
            "tone": "no",
            "maraji": []
          },
          {
            "ruling": "اجتناب المرأة الحناء إذا كان سيبقى إلى الإحرام.",
            "tone": "no",
            "maraji": []
          },
          {
            "ruling": "الغسل والدعاء عنده، والدعاء عند لبس ثياب الإحرام.",
            "tone": "no",
            "maraji": []
          },
          {
            "ruling": "السكينة والتواضع وقلة الكلام إلا بخير، فإن من تمام الحج حفظ اللسان.",
            "tone": "no",
            "maraji": []
          },
          {
            "ruling": "الإحرام بعد الفريضة وإلا بعد نافلةٍ من ست ركعات أو ركعتين، ثم قراءة دعاء الاشتراط.",
            "tone": "no",
            "maraji": []
          }
        ]
      },
      {
        "opinions": [
          {
            "ruling": "حبذا التفكر في آداب الإحرام وغيرها: فينوي عند تنظيف الإبطين وتقليم الأظفار مثلًا أنه ينظف باطنه وقلبه من الطباع السيئة والأخلاق المذمومة المختبئة في زوايا النفس، ويقطع كل صفة تشوه ظاهره وباطنه أمام الله وعباده الصالحين.",
            "tone": "no",
            "maraji": []
          },
          {
            "ruling": "تنبيه — إزالة شعر الإبطين والعانة قبل السفر: تُجَنِّبُ المكلَّفَ أيَّ جرحٍ قد يُؤذيه أثناء المناسك.. وهذا مما يُسهِّل أعمال الميقات الذي قد تكتنفه بعض الصعوبات من برد أو حر أو ازدحام.",
            "tone": "detail",
            "maraji": []
          },
          {
            "ruling": "السكينة والتواضع ضرورة. الإمام الصادق (عليه السلام): مَن دخلها (مكة) بسكينة غُفِرَ له ذنبُه. قلت: كيف يدخلها بسكينة؟ قال: يدخل غير متكبر ولا متجبر. وفي رواية.. قلت: ما السكينة؟ قال: يتواضع. التواضع وتجنب كثرة الكلام.. أمرٌ مطلوبٌ كما روي قبل الإحرام وبعده.. وفي كل حال وآن.",
            "tone": "no",
            "maraji": []
          }
        ],
        "label": "من آداب الإحرام: التفكر، والتنبيه، والسكينة"
      },
      {
        "opinions": [
          {
            "ruling": "مستحبٌّ مؤكَّد.. حتى أن الحائض يمكنها الإتيان به. ويجوز أداؤه قبل الميقات.",
            "tone": "no",
            "maraji": []
          },
          {
            "ruling": "وقد يُفهَم من عبارة صاحب الحدائق (ج4 ص184) الوجوب: (القول بالوجوب لا يخلو من قوة، والاحتياط يقتضي المحافظة عليه). لكنه ذهب في مناسكه إلى استحبابه، ويجزي العمل به لا سيما أن مبنى الشيخ جواز العمل بالفتوى مطلقًا.",
            "tone": "detail",
            "maraji": [
              "usfur"
            ]
          },
          {
            "ruling": "الأحوط أن ينوي المكلف: غسل الإحرام + غسل ما في ذمته (رجاءً).",
            "tone": "ihtiyat",
            "maraji": []
          },
          {
            "ruling": "نُسِبَ للإمام الصادق: ثُمَّ اغسِل بِماءِ التَّوبَةِ الخالِصَةِ ذُنوبَكَ، والبَس كِسوَةَ الصِّدقِ والصَّفاءِ والخُضوعِ والخُشوعِ، وأحرِم مِن كُلِّ شَيءٍ يَمنَعُكَ عَن ذِكرِ اللهِ ويَحجُبُكَ عَن طاعَتِهِ..",
            "tone": "detail",
            "maraji": []
          },
          {
            "ruling": "دعاء غسل الإحرام: بسم الله وبالله، اللهم اجعله لي نورًا وطهورًا وحرزًا وأمنًا من كل خوف، وشفاءً من كل داء وسقم، اللهم طهِّرني وطهِّر قلبي، واشرح لي صدري، وأَجْرِ على لساني محبَّتَك ومدحَتَكَ والثناءَ عليك، فإنَّه لا قوَّةَ لي إلا بك، وقد علمتُ أنَّ قوامَ ديني التسليمُ لأمرك والاتباع لسنة نبيك صلواتك عليه وآله.",
            "tone": "detail",
            "maraji": []
          }
        ],
        "label": "غسل الإحرام"
      }
    ],
    "status": "draft",
    "source": "يُنظَر: (العمل الصادق من مسائل الحدائق) ج1 ص114."
  },
