  "umrah_mufrada-099": {
    "q": "آدابٌ بعد الإحرام",
    "cases": [
      {
        "opinions": [
          {
            "ruling": "التَّشَبُّه بالمحرمين: بعد الإحلال الأول (التقصير) إلى طواف النساء.",
            "tone": "no",
            "maraji": []
          },
          {
            "ruling": "طواف الوداع والإتيان بأدعية وأعمال وداع مكة، كـ: شرب زمزم، السجود، الصدقة.",
            "tone": "no",
            "maraji": []
          },
          {
            "ruling": "نيَّة العَود (الصادق عليه السلام): من رجع وهو ينوي الحج زيد في عمره.. ومن لا يريد العود اقترب أجله وعذابه.",
            "tone": "no",
            "maraji": []
          },
          {
            "ruling": "زيارة النبي وأهله والمواضع المتصلة بهم لتجديد مبايعتهم، وتصحيح العمل، وتصفية النفس. نظر الإمام الباقر إلى الناس يطوفون حول الكعبة، فقال: هكَذا كانوا يَطوفونَ فِي الجاهِلِيَّةِ.. إنَّما أُمِروا أن يَطوفوا بِها، ثُمَّ يَنفِروا إلَينا.. فَيُعلِموا وَلايَتَهُم، ومَوَدَّتَهُم، ويَعرِضوا عَلَينا نُصرَتَهُم. ثُمَّ قَرَأَ: (فَاجعَل أفئِدَةً مِنَ النّاسِ تَهوي إلَيهِم).",
            "tone": "no",
            "maraji": []
          }
        ]
      }
    ],
    "status": "draft"
  },
