    "source": "الحبوة، زين الدين م579، جامع الأحكام للناصر. ح العصفور: مصباح الناسكين، أما في (دليل الحرمين) خلاصة (ابتهاج الحاج) للعلامة ص29 فقد ذكر فقط أن الإضمار أفضل وأحوط. فضل الله: ذكر في كيفية الإحرام أنه لا يعتبر التلفظ، وقيل يستحب. مناسك المدرسي في عدة مواضع.",
