  "umrah_mufrada-162": {
    "q": "الحرم المكي.. أعلامه وحدوده",
    "cases": [
      {
        "opinions": [
          {
            "ruling": "حدود الحرم: حُدِّدت في الروايات (بريد في بريد). والبريد 4 فراسخ شرعية، فتكون المساحة التقريبية للحرم 16 فرسخًا مربعًا.",
            "tone": "detail",
            "maraji": []
          },
          {
            "ruling": "مساحة الحرم: 556 كم مربع. طول محيطه (المسار) = 141 كم تقريبًا. طول الحد الشمالي 50 كم، الجنوبي 43 كم، الشرقي 30 كم، الغربي 18 كم. عدد الأعلام على حدود الحرم 1104. أقرب علَم للكعبة يقع في (التنعيم) بمسافة 5.2 كم. أبعد علَم عن الكعبة يقع على (جبل الموشح) في الحد الغربي بمسافة 21.2 كم.",
            "tone": "detail",
            "maraji": []
          },
          {
            "ruling": "سأل البزنطي الإمام الرضا (عليه السلام) عن الحرم وأعلامه: كيف صار بعضها أقرب من بعض، وبعضها أبعد من بعض؟ فقال (عليه السلام): إن الله عز وجل لما أهبط آدم (عليه السلام) من الجنة أهبط على (أبي قبيس). فشكا إلى ربه عز وجل الوحشة وأنه لا يسمع ما كان يسمع في الجنة. فأهبط الله عز وجل إليه ياقوتة حمراء فوضعها في موضع البيت. فكان يطوف بها آدم (عليه السلام) وكان ضوؤها يبلغ موضع الأعلام فعلمت الأعلام على ضوئها فجعله الله حرمًا.",
            "tone": "detail",
            "maraji": []
          }
        ]
      },
      {
        "opinions": [
          {
            "ruling": "من حد الحرم (ثنيَّة خلّ) إلى الكعبة 13,86 كم. ومنه إلى مسجد حنين 2 كم، وإلى ملعب الشرائع 3,3 كم، ولمسجد الجعرانة 9,11 كم. من مسجد الجعرانة إلى جبل الرحمة 23,87 كم، ومن الجسر الذي يتقاطع مع طريق السيل إلى سوق ذي المجاز 6,44 كم. الاتجاه جنوبًا إلى عرفات: من (ملعب الشرائع) إلى (جبل الرحمة) 14,3 كم.",
            "tone": "detail",
            "maraji": []
          }
        ],
        "label": "خرائط: حد الحرم عند ثنية خلّ المقطَّع"
      }
    ],
    "status": "draft"
  },
  "umrah_mufrada-164": {
    "q": "من تاريخ حدود الحرم",
    "cases": [
      {
        "opinions": [
          {
            "ruling": "يقول مؤرخو مكة: إن حدود الحرم وُضعت منذ أيام النبي آدم (عليه السلام)؛ لأنه خاف على نفسه من الشياطين؛ فاستعاذ بالله؛ فأرسل الله الملائكة، فحفوا بمكة من كل جانب.",
            "tone": "detail",
            "maraji": []
          },
          {
            "ruling": "وهناك رواية تقول: إن إبراهيم (عليه السلام) عندما أراد بناء البيت أمر الله الملائكةَ بأن تقف على هذه الأعلام حتى لا تدخل الشياطين والجن إلى مكة حتى اكتمل بناء الكعبة.",
            "tone": "detail",
            "maraji": []
          },
          {
            "ruling": "وهناك رواية، تقول: إن إبراهيم الخليل (عليه السلام) عندما قدم مكة بزوجته وابنه إسماعيل (عليه السلام)، ودعا لهما {ربنا وأرنا مناسكنا}، نزل إليه جبريل (عليه السلام)، فذهب به، فأراه المناسك كلها، وأوقفه على حدود الحرم، فكان جبريل يشير إليه بالمواقع، وإبراهيم يرضم الحجارة، وينصب الأعلام، ويذر عليها التراب.",
            "tone": "detail",
            "maraji": []
          }
        ]
      },
      {
        "opinions": [
          {
            "ruling": "في عهد رسول الله.. وقيل في بعض غزوات قريش علمت قريش أنه (صلى الله عليه وآله) يهتم بحدود الحرم فأرادت أن تؤذيه.. فألقت بعض حدود الحرم فاشتد على المصطفى ذلك. فجاءه جبريل، وقال له: \"يا محمد، هل اشتد عليك أن نزعت قريش أنصاب الحرم؟\". فقال: \"نعم\". فقال جبريل: \"أما إنهم سيعيدونها إلى أماكنها\". ثم إنه جاء ونادى في قبائل قريش: أما تستحيون أن الله تعالى أكرمكم بهذا البيت وهذا الحرم، وقد ضيعتم حدوده.. والآن يذلونكم ويتخطفونكم. فقالوا: صدقت. فجاؤوا فوضعوا كل علامة قلعت في موضعها. فجاء جبرئيل إلى النبي (صلى الله عليه وآله) وقال: كل عَلَم قُلِعَ وضعوه في محلِّه. فقال (صلى الله عليه وآله): \"إن شاء اللهُ أصابوا محلَّه\". فقال جبرئيل: ما وضعوا حجرًا في محله إلا كان معه ملكٌ لئلا يُخطئوا. \"والله لن يضعوا حجرًا إلا بيد ملك\".",
            "tone": "detail",
            "maraji": []
          }
        ],
        "label": "قريش تعبث بالأعلام فتتدخل السماء.. ليرضى محمد"
      },
      {
        "opinions": [
          {
            "ruling": "إذ لا يبعد العَلَم عن الآخر إلا أمتارًا معدودة. وتختلف المسافات بناءً على التضاريس. وكانت الحجارة مبنية ومرضومة بعضها فوق بعض بشكل مربع تقريبًا، وهي لم توضع اعتباطًا. فكل عَلَمٍ بُني على نقطة معروفة عند الجغرافيين تسمى: نقطة تقسيم المياه، وهي: إذا صُبَّ الماء فيها على الجبل فإنه يسيح إما يمينًا أو يسارًا، فما سال يسارًا فهو في الحرم، وما سال يمينًا فهو في الحل.",
            "tone": "detail",
            "maraji": []
          },
          {
            "ruling": "إذا انحرف العَلَم يمينًا أو يسارًا فيُبنى على شكل زاوية ليشير للعَلَم الذي بعده. والحجارة التي بُنيَت بها ليست من حجارة الجبال نفسها، وتختلف عن أحجار الجبال نفسها، وهي معجزة أخرى.",
            "tone": "detail",
            "maraji": []
          }
        ],
        "label": "وضع الأعلام على رؤوس الجبال آية من الآيات"
      }
    ],
    "status": "draft"
  },
